'use strict';
/* ---------- Início ---------- */
function home(){const m=nextMethod(),started=totalDone()>0,sys=s.featTab==='systems';
 const features=[
  [sys?'Veja a matriz mudar, linha por linha':'Visual e interativo, não um gabarito',sys?'Na Eliminação de Gauss, cada operação aparece de verdade: trocas de linha, zeros abaixo da diagonal e substituição regressiva. Você acompanha a mesma matriz que o motor calcula.':'Cada método aparece como uma ideia que você vê funcionar. Na Bisseção, o intervalo cai pela metade a cada passo até cercar a raiz.','Você controla o ritmo: avance ou volte um passo de cada vez na simulação.',sys?gaussPreview():bisectionPreview(),'tint-peach'],
  ['Feedback na hora, dica antes do gabarito','Cada etapa tem uma pergunta curta. Se errar, você recebe uma orientação e tenta de novo. A explicação completa aparece quando você acerta.','Estrelas registram a sua melhor tentativa: três para acerto sem dica e sem erro.',questionMock(sys?C.TASKS.gauss[0]:C.TASKS.bisection[0]),'tint-sage'],
  [sys?'Convergência que dá para medir':'Revisão no tempo certo',sys?'No Gauss-Seidel, você vê o resíduo cair a cada iteração e entende quando é seguro parar. O mesmo critério vale para o terminal.':'As questões difíceis vão para o caderno de revisão e voltam depois de 1, 3, 7 e 14 dias, conforme você acerta sem ajuda.',sys?'O critério usa resíduo normalizado e variação relativa, não um número mágico.':'Repetir uma questão melhora as estrelas, mas não multiplica o XP.',sys?seidelPreview():reviewMock(),'tint-sky']];
 const HIDDEN_TITLES=(C.HIDDEN||[]).map(id=>method(id).title);const topics={roots:['Bisseção','Falsa Posição','Ponto Fixo','Newton-Raphson','Secante','Raiz e mudança de sinal','Iteração e critério de parada','Resíduo e erro','Tolerância','Ordem de convergência'],systems:['Eliminação de Gauss','Gauss-Seidel','Pivoteamento parcial','Substituição regressiva','Resíduo normalizado','Convergência iterativa','Sistemas sem solução única','Tolerância'],modeling:C.CASES.map(c=>c.title).concat(['Formular, calcular e interpretar','Unidades e domínio físico','Validar a solução']),practice:['Jogos',`${TR?TR.count:0} exercícios de diagnóstico no Treino`,'Modo prova com nota e relatório','Caderno de revisão espaçada','Estrelas por melhor tentativa','XP e níveis','8 conquistas','Backup do progresso']};topics.roots=topics.roots.filter(t=>!HIDDEN_TITLES.includes(t));topics.practice.splice(0,1,'Calculândia, a aventura 3D com 63 fases','Bobo da Corte, o jogo da turma no telão');topics.practice.splice(5,2,'XP, moedas e níveis','Raiz e Pivô, o casal que torce por você',`${badgeList().length} conquistas`);
 const topicTabs=[['roots','Raízes'],['systems','Sistemas'],['modeling','Modelagem'],['practice','Prática']];
 const topicCta={roots:['Começar com Bisseção','course','bisection'],systems:['Começar com Gauss','course','gauss'],modeling:['Ver as missões','nav','cases'],practice:['Ver os jogos','nav','jogos']}[s.topicsTab];
 return `<section class="hero-band"><div class="wrap hero"><div class="hero-copy"><h1 class="display">Aprenda métodos numéricos resolvendo de verdade</h1><p class="lead">Um laboratório interativo de Modelagem Computacional. Entenda a ideia, veja o método funcionar e pratique até dominar.</p><div class="hero-actions">${btn(started?'Continuar de onde parei':'Começar a aprender','course','primary big',`data-id="${m.id}"`)}${btn('Abrir o terminal','nav','ghost big','data-page="lab"')}</div><div class="hero-badges"><span>${icon('check')}Funciona offline</span><span>${icon('check')}Sem conta</span><span>${icon('check')}Cálculos no navegador</span></div></div><div class="hero-card" id="hero-widget">${heroWidget()}</div></div></section>
 <section class="wrap stats" aria-label="O projeto em números"><div><b>${C.METHODS.length}</b><span>métodos numéricos</span></div><div><b>${visibleIds().length}</b><span>atividades com progresso</span></div><div><b>${TR?TR.count:0}</b><span>exercícios no Treino</span></div><div><b>${VERIFY_COUNT.toLocaleString('pt-BR')}</b><span>verificações automáticas</span></div></section>
 <section class="wrap section meet"><h2 class="display center">Um conceito por vez, sempre com as mãos no problema</h2><div class="seg center-seg" role="group" aria-label="Tema">${[['roots','Raízes de equações'],['systems','Sistemas lineares']].map(([id,t])=>`<button type="button" data-act="feat" data-id="${id}" class="${s.featTab===id?'active':''}" aria-pressed="${s.featTab===id}">${t}</button>`).join('')}</div><div class="feature-rows">${features.map(([t,a,b2,media,tint],i)=>`<div class="feature ${i%2?'flip':''}"><div class="feature-text"><h3>${t}</h3><p>${a}</p><p>${b2}</p></div><div class="feature-media ${tint}"><div class="media-card">${media}</div></div></div>`).join('')}</div></section>
 <section class="band-white"><div class="wrap section"><h2 class="display center">Eficaz e transparente</h2><div class="trust-grid"><article class="trust-card"><div class="trust-visual tint-sand"><code>x³ − 4 = 0</code><small>aresta do reservatório ≈ ${short(C.CASES[0].tasks[2].value)} m</small></div><h3>Missões de modelagem</h3><p>${cap(words(C.CASES.length))} problemas aplicados, cada um em três partes: formular a equação, calcular e interpretar o resultado.</p></article><article class="trust-card"><div class="trust-visual dark">${teaserScreen()}</div><h3>Terminal com verificação</h3><p>Digite uma equação ou um sistema e veja a comparação entre métodos, a tabela de iterações e a substituição da resposta.</p></article><article class="trust-card"><div class="trust-visual tint-lilac"><ul class="dash-list compact"><li>Encontrar todas as raízes</li><li>Um método sempre mais rápido</li></ul></div><h3>Limites declarados</h3><p>O Numera diz o que não garante. Resíduo pequeno não significa erro pequeno, e ausência de raiz encontrada não prova que ela não existe.</p></article></div></div></section>
 <section class="wrap section topics"><h2 class="display center">Do primeiro palpite ao domínio</h2><div class="seg center-seg" role="group" aria-label="Área">${topicTabs.map(([id,t])=>`<button type="button" data-act="topics" data-id="${id}" class="${s.topicsTab===id?'active':''}" aria-pressed="${s.topicsTab===id}">${t}</button>`).join('')}</div><div class="topics-card"><div><span class="eyebrow">Tópicos cobertos</span><ul class="topic-list">${topics[s.topicsTab].map(t=>`<li>${icon('check')}${safe(t)}</li>`).join('')}</ul></div><div class="topics-cta">${s.topicsTab==='roots'||s.topicsTab==='systems'?`<div class="topic-arts">${(s.topicsTab==='roots'?ROOTS():SYSTEMS()).map(m=>m.id).map(id=>`<button type="button" class="topic-art tone-${id}" data-act="course" data-id="${id}" aria-label="${method(id).title}">${art(id)}<span>${method(id).title}</span></button>`).join('')}</div>`:''}${btn(topicCta[0]+' '+icon('arrow'),topicCta[1],'primary',topicCta[1]==='course'?`data-id="${topicCta[2]}"`:`data-page="${topicCta[2]}"`)}</div></div></section>
 <section class="wrap section"><div class="feature"><div class="feature-text"><h3>No seu ritmo, até sem internet</h3><p>Não precisa de conta nem de servidor. O progresso fica salvo no seu navegador, e você leva tudo para outro computador com um backup em JSON.</p><p>Uma meta diária de três atividades e a sequência de dias ajudam a manter o hábito.</p></div><div class="feature-media tint-sand"><div class="media-card">${calendarMock()}</div></div></div><div class="feature flip"><div class="feature-text"><h3>Feito com método</h3><p>Um interpretador próprio lê as equações sem usar <code>eval()</code>. Os ${words(C.METHODS.length)} métodos passam por uma suíte de ${VERIFY_COUNT.toLocaleString('pt-BR')} verificações automáticas.</p><div class="refs"><span>Driscoll &amp; Braun</span><span>Netlib Templates</span><span>Modelagem Computacional</span></div></div><div class="feature-media tint-peach"><div class="media-card"><span class="eyebrow">Newton-Raphson em pseudocódigo</span><pre class="pseudocode" tabindex="0" aria-label="Pseudocódigo">${safe(C.DEEP.newton.pseudo)}</pre></div></div></div></section>
 <section class="cta-band"><div class="wrap cta-inner"><h2 class="display">A próxima raiz começa com um palpite</h2>${btn((started?'Continuar':'Começar agora')+' '+icon('arrow'),'course','light big',`data-id="${m.id}"`)}</div></section>`;}

